<script setup>import{onMounted,ref}from'vue';import{api}from'../../api/http.js';import PageHeader from'../../components/common/PageHeader.vue';import T from'../../components/common/WorkspaceTable.vue';const rows=ref([]),employees=ref([]),error=ref(''),form=ref({employee_id:'',pay_period_start:'',pay_period_end:'',regular_hours:80,overtime_hours:0,allowances:0,bonuses:0,deductions:0});const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n||0);async function load(){try{const[d,e]=await Promise.all([api.payroll(),api.employees({per_page:100})]);rows.value=d.data;employees.value=e.data}catch(x){error.value=x.message}}async function save(){try{await api.post('/payroll',form.value);await load()}catch(x){error.value=x.message}}async function review(id,decision){try{await api.post(`/payroll/${id}/review`,{decision});await load()}catch(x){error.value=x.message}}onMounted(load)</script><template><PageHeader title="Payroll" description="Prepare, approve, and mark payroll as paid."/><p v-if="error" class="form-error">{{error}}</p><form class="inline-form" @submit.prevent="save"><select v-model="form.employee_id" required><option value="">Employee</option><option v-for="e in employees" :value="e.id">{{e.full_name}}</option></select><input v-model="form.pay_period_start" type="date" required><input v-model="form.pay_period_end" type="date" required><input v-model.number="form.regular_hours" type="number" placeholder="Regular hours"><input v-model.number="form.overtime_hours" type="number" placeholder="OT hours"><button class="primary-button">Create payroll</button></form><T :columns="[{key:'full_name',label:'Employee'},{key:'pay_period_end',label:'Period end'},{key:'net_pay',label:'Net pay'},{key:'status',label:'Status'}]" :rows="rows"><template #cell-net_pay="{row}">{{money(row.net_pay)}}</template><template #actions="{row}"><button v-if="row.status==='Draft'" @click="review(row.id,'Approved')">Approve</button><button v-if="row.status==='Approved'" @click="review(row.id,'Paid')">Mark paid</button></template></T></template>